// Generated by grafana-k6 on 2026-11-08T14:39:27Z
import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Counter, Trend } from 'k6/metrics';

const baseUrl = (__ENV.BASE_URL || '').replace(/\/$/, '');
const smoke = __ENV.SMOKE === '1';
const adminEmail = __ENV.ADMIN_EMAIL || '';
const adminPassword = __ENV.ADMIN_PASSWORD || '';
const testUserPassword = __ENV.TEST_USER_PASSWORD || '';
const testUserDomain = __ENV.TEST_USER_DOMAIN || 'example.com';
const userCount = smoke ? 1 : 100;
const reportName = __ENV.REPORT_NAME === 'smoke' ? 'smoke' : 'latest';
const operations = ['folder_list', 'article_list', 'test_list', 'article_open', 'test_open'];
const endpointDurations = Object.fromEntries(operations.map((operation) => [operation, new Trend(`api_${operation}_duration`, true)]));
const endpointRequests = Object.fromEntries(operations.map((operation) => [operation, new Counter(`api_${operation}_requests`)]));

export const options = {
  setupTimeout: '5m',
  scenarios: {
    mobile_read: {
      executor: 'ramping-vus',
      startVUs: 0,
      stages: smoke
        ? [{ duration: '5s', target: 1 }, { duration: '10s', target: 1 }, { duration: '5s', target: 0 }]
        : [{ duration: '2m', target: 100 }, { duration: '5m', target: 100 }, { duration: '1m', target: 0 }],
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.01'],
    http_req_duration: ['p(95)<1000', 'p(99)<2000'],
    checks: ['rate>0.99'],
  },
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
};

export function setup() {
  if (!/^https?:\/\/[^/]+$/i.test(baseUrl)) throw new Error('BASE_URL must be an explicit HTTP(S) origin');
  if (!adminEmail || !adminPassword || !testUserPassword || testUserPassword.length < 6) {
    throw new Error('Set ADMIN_EMAIL, ADMIN_PASSWORD and TEST_USER_PASSWORD (minimum 6 characters)');
  }
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(testUserDomain)) throw new Error('TEST_USER_DOMAIN must be a valid domain');

  const adminLogin = http.post(`${baseUrl}/api/v1/auth/login/json`, JSON.stringify({ email: adminEmail, password: adminPassword, device_name: 'k6-provisioner' }), { headers: { 'Content-Type': 'application/json' } });
  if (!check(adminLogin, { 'admin login succeeded': (r) => r.status === 200 && !!r.json('session_id') })) {
    throw new Error(`Admin login failed with HTTP ${adminLogin.status}`);
  }
  const adminSession = adminLogin.json('session_id');
  const adminHeaders = { 'Content-Type': 'application/json', 'X-Session-Id': adminSession };
  const usersResponse = http.get(`${baseUrl}/api/v1/users`, { headers: adminHeaders });
  if (usersResponse.status !== 200) throw new Error(`Could not list existing users (HTTP ${usersResponse.status})`);
  const existingUsers = new Set(usersResponse.json().map((user) => String(user.email).toLowerCase()));
  const sessions = [];

  for (let i = 1; i <= userCount; i++) {
    const suffix = String(i).padStart(3, '0');
    const email = `k6-load-${suffix}@${testUserDomain}`;
    if (!existingUsers.has(email)) {
      const created = http.post(`${baseUrl}/api/v1/users`, JSON.stringify({ email, fullName: `K6 Load User ${suffix}`, role: 'user', password: testUserPassword }), { headers: adminHeaders });
      if (created.status !== 201) throw new Error(`Could not create ${email} (HTTP ${created.status}): ${created.body}`);
    }
    const login = http.post(`${baseUrl}/api/v1/auth/login/json`, JSON.stringify({ email, password: testUserPassword, device_name: `k6-vu-${suffix}` }), { headers: { 'Content-Type': 'application/json' } });
    if (!check(login, { 'test user login succeeded': (r) => r.status === 200 && !!r.json('session_id') })) {
      throw new Error(`Could not log in as ${email} (HTTP ${login.status}); check the configured test password and existing account`);
    }
    sessions.push(login.json('session_id'));
  }
  return { sessions };
}

export default function (data) {
  const headers = { 'X-Session-Id': data.sessions[exec.vu.idInTest - 1] };
  const getArray = (path, operation) => {
    const response = http.get(`${baseUrl}${path}`, { headers, tags: { name: operation } });
    endpointDurations[operation].add(response.timings.duration);
    endpointRequests[operation].add(1);
    let body;
    try { body = response.json(); } catch (_) { body = null; }
    check(response, { [`${operation}: HTTP 200 array`]: (r) => r.status === 200 && Array.isArray(body) });
    return Array.isArray(body) ? body : [];
  };
  const choose = (items) => {
    const accessible = items.filter((item) => !item.isLocked);
    return accessible.length ? accessible[Math.floor(Math.random() * accessible.length)] : null;
  };

  const roots = getArray('/api/v1/folders?enforceTariff=true', 'folder_list');
  sleep(1 + Math.random() * 2);
  const pendingFolders = roots.filter((folder) => !folder.isLocked);
  const visited = new Set();
  // If one folder is empty, continue browsing another instead of ending the user journey.
  for (let visit = 0; visit < 4 && pendingFolders.length; visit++) {
    const currentFolder = pendingFolders.splice(Math.floor(Math.random() * pendingFolders.length), 1)[0];
    if (visited.has(currentFolder.id)) continue;
    visited.add(currentFolder.id);
    const parentId = encodeURIComponent(currentFolder.id);
    const [children, articles, tests] = [
      getArray(`/api/v1/folders?parentId=${parentId}&enforceTariff=true`, 'folder_list'),
      getArray(`/api/v1/articles?parentId=${parentId}&enforceTariff=true`, 'article_list'),
      getArray(`/api/v1/tests?parentId=${parentId}&enforceTariff=true`, 'test_list'),
    ];
    sleep(1 + Math.random() * 2);

    const article = choose(articles);
    const test = choose(tests);
    if (article || test) {
      const openArticle = article && (!test || Math.random() < 0.7);
      const material = openArticle ? article : test;
      const kind = openArticle ? 'articles' : 'tests';
      const operation = openArticle ? 'article_open' : 'test_open';
      const response = http.get(`${baseUrl}/api/v1/${kind}/${encodeURIComponent(material.id)}?enforceTariff=true`, { headers, tags: { name: operation } });
      endpointDurations[operation].add(response.timings.duration);
      endpointRequests[operation].add(1);
      let item;
      try { item = response.json(); } catch (_) { item = null; }
      check(response, { [`${operation}: HTTP 200 item`]: (r) => r.status === 200 && !!item && !Array.isArray(item) });
      sleep(4 + Math.random() * 8); // reading / viewing the opened material
      return;
    }

    for (const child of children.filter((item) => !item.isLocked && !visited.has(item.id))) pendingFolders.push(child);
    sleep(1 + Math.random() * 2);
  }
}

export function handleSummary(data) {
  const metrics = data.metrics;
  const metric = (name, key) => metrics[name]?.values?.[key] ?? null;
  const operationMetrics = Object.fromEntries(operations.map((operation) => {
    const values = metrics[`api_${operation}_duration`]?.values;
    const count = metrics[`api_${operation}_requests`]?.values?.count ?? 0;
    return [operation, values ? { count, averageMs: values.avg, p95Ms: values['p(95)'], p99Ms: values['p(99)'] } : null];
  }));
  const htmlEscape = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  const report = {
    createdAt: new Date().toISOString(),
    target: baseUrl,
    virtualUsers: userCount,
    requests: metric('http_reqs', 'count'),
    requestsPerSecond: metric('http_reqs', 'rate'),
    failedRequestRate: metric('http_req_failed', 'rate'),
    checksPassed: metric('checks', 'passes'),
    checksFailed: metric('checks', 'fails'),
    operations: operationMetrics,
    responseTimeMs: {
      average: metric('http_req_duration', 'avg'),
      p95: metric('http_req_duration', 'p(95)'),
      p99: metric('http_req_duration', 'p(99)'),
      maximum: metric('http_req_duration', 'max'),
    },
  };
  const rows = Object.entries(report.responseTimeMs).map(([label, value]) => `<tr><th>${label}</th><td>${value === null ? 'n/a' : `${value.toFixed(1)} ms`}</td></tr>`).join('');
  const endpointRows = Object.entries(operationMetrics).map(([name, values]) => `<tr><th>${name}</th><td>${values ? `${values.count} · p95 ${values.p95Ms?.toFixed(1) ?? 'n/a'} ms` : 'не вызывался'}</td></tr>`).join('');
  const html = `<!doctype html><html lang="ru"><meta charset="utf-8"><title>Отчёт k6</title><style>body{font:16px system-ui;max-width:760px;margin:40px auto;padding:0 20px;color:#17202a}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd}th{width:55%}small{color:#566}</style><h1>Нагрузочный тест мобильного API</h1><p>${report.createdAt}</p><p>Цель: ${htmlEscape(report.target)} · виртуальных пользователей: ${report.virtualUsers}</p><table><tr><th>Запросы</th><td>${report.requests ?? 'n/a'}</td></tr><tr><th>Запросов в секунду</th><td>${report.requestsPerSecond?.toFixed(2) ?? 'n/a'}</td></tr><tr><th>Доля ошибок</th><td>${report.failedRequestRate === null ? 'n/a' : `${(report.failedRequestRate * 100).toFixed(2)}%`}</td></tr><tr><th>Проверки пройдены / ошибки</th><td>${report.checksPassed ?? 'n/a'} / ${report.checksFailed ?? 'n/a'}</td></tr>${rows}${endpointRows}</table><small>См. также latest.json в этой папке.</small></html>`;
  return { [`k6/reports/${reportName}.json`]: JSON.stringify(report, null, 2), [`k6/reports/${reportName}.html`]: html };
}
